using System.Globalization;

namespace GKRStudio.Core;

/// <summary>
/// Localization. The Turkish text is the key; English, Dutch and French come from the table below.
/// Unknown strings fall back to Turkish, so nothing ever breaks when a translation is missing.
/// </summary>
public static class L
{
    public static readonly (string Code, string Name)[] Languages = [("tr", "Türkçe"), ("en", "English"), ("nl", "Nederlands"), ("fr", "Français")];

    /// <summary>Current language; refreshed whenever settings are loaded.</summary>
    public static string Lang { get; set; } = "tr";

    public static string T(string tr)
    {
        if (Lang == "tr" || string.IsNullOrEmpty(tr)) return tr;
        if (Table.TryGetValue(tr, out var t)) return Pick(t);
        string trimmed = tr.Trim();
        if (trimmed != tr && Table.TryGetValue(trimmed, out t)) return tr.Replace(trimmed, Pick(t));
        return tr;
    }

    public static string F(string trFormat, params object[] args) => string.Format(CultureInfo.CurrentCulture, T(trFormat), args);

    /// <summary>Best effort for runtime messages: per line, exact match or a known "prefix: rest" key.</summary>
    public static string Msg(string message)
    {
        if (Lang == "tr" || string.IsNullOrEmpty(message)) return message;
        return string.Join("\n", message.Split('\n').Select(line =>
        {
            if (Table.ContainsKey(line.Trim())) return T(line);
            var key = Prefixes.FirstOrDefault(k => line.StartsWith(k, StringComparison.Ordinal));
            return key == null ? line : T(key) + line[key.Length..];
        }));
    }

    private static string Pick((string En, string Nl, string Fr) t) => Lang switch { "en" => t.En, "nl" => t.Nl, "fr" => t.Fr, _ => t.En };

    private static readonly string[] Prefixes;

    static L()
    {
        Prefixes = Table.Keys.Where(k => k.EndsWith(": ", StringComparison.Ordinal)).OrderByDescending(k => k.Length).ToArray();
    }

