        // errors (most common)
        ["Güvenli bağlantı doğrulanamadı. Antivirüsün HTTPS taraması ya da bir proxy bağlantıyı değiştiriyor olabilir; Windows saatinin doğru olduğundan emin olun."] = ("The secure connection could not be verified. Antivirus HTTPS scanning or a proxy may be altering it; also check the Windows clock.", "De beveiligde verbinding kon niet worden geverifieerd. HTTPS-scanning van een virusscanner of een proxy kan haar wijzigen; controleer ook de Windows-klok.", "La connexion sécurisée n'a pas pu être vérifiée. L'analyse HTTPS d'un antivirus ou un proxy peut la modifier ; vérifiez aussi l'horloge."),
        ["Bu içerik giriş yapmayı gerektiriyor; yalnızca herkese açık medya indirilebilir."] = ("This content requires signing in; only public media can be downloaded.", "Voor deze inhoud moet u inloggen; alleen openbare media kunnen worden gedownload.", "Ce contenu nécessite une connexion ; seuls les médias publics peuvent être téléchargés."),
        ["Video özel; indirilemez."] = ("The video is private and cannot be downloaded.", "De video is privé en kan niet worden gedownload.", "La vidéo est privée et ne peut pas être téléchargée."),
        ["Bu site ya da sayfa desteklenmiyor. Doğrudan video sayfasının linkini kopyalayın."] = ("This site or page is not supported. Copy the link of the video page itself.", "Deze site of pagina wordt niet ondersteund. Kopieer de link van de videopagina zelf.", "Ce site ou cette page n'est pas pris en charge. Copiez le lien de la page vidéo."),
        ["İstenen biçim bu videoda yok."] = ("The requested format is not available for this video.", "Het gevraagde formaat is niet beschikbaar voor deze video.", "Le format demandé n'est pas disponible pour cette vidéo."),
        ["Site çok fazla istek nedeniyle geçici olarak engelledi; biraz sonra tekrar deneyin."] = ("The site is temporarily blocking too many requests; try again later.", "De site blokkeert tijdelijk te veel verzoeken; probeer het later opnieuw.", "Le site bloque temporairement trop de requêtes ; réessayez plus tard."),
        ["İnternet bağlantısı yok ya da site adı çözülemedi."] = ("No internet connection, or the site name could not be resolved.", "Geen internetverbinding of de sitenaam kon niet worden opgezocht.", "Pas de connexion Internet ou nom de site introuvable."),
        ["İndirme başarısız oldu. yt-dlp'yi güncellemek çoğu zaman çözer (Ayarlar → Eksik araçları kur / winget upgrade yt-dlp.yt-dlp)."] = ("The download failed. Updating yt-dlp often fixes this (winget upgrade yt-dlp.yt-dlp).", "Downloaden mislukt. yt-dlp bijwerken lost dit vaak op (winget upgrade yt-dlp.yt-dlp).", "Le téléchargement a échoué. Mettre à jour yt-dlp règle souvent le problème (winget upgrade yt-dlp.yt-dlp)."),
        ["Sunumlar için LibreOffice veya Microsoft PowerPoint gerekli."] = ("Presentations need LibreOffice or Microsoft PowerPoint.", "Presentaties vereisen LibreOffice of Microsoft PowerPoint.", "Les présentations nécessitent LibreOffice ou Microsoft PowerPoint."),
        ["PDF'te seçilebilir metin yok (taranmış belge olabilir)."] = ("The PDF has no selectable text (it may be a scan — try OCR).", "De pdf heeft geen selecteerbare tekst (mogelijk een scan — probeer OCR).", "Le PDF n'a pas de texte sélectionnable (peut-être un scan — essayez l'OCR)."),
        ["Windows OCR için dil paketi yok. Ayarlar → Saat ve dil → Dil'den Türkçe (veya İngilizce) paketini ekleyin."] = ("No language pack for Windows OCR. Add one under Settings → Time & language → Language.", "Geen taalpakket voor Windows OCR. Voeg er een toe via Instellingen → Tijd en taal → Taal.", "Aucun pack de langue pour l'OCR Windows. Ajoutez-en un dans Paramètres → Heure et langue → Langue."),
