        // ---------- settings window ----------
        ["Görsel ve medya dönüştürme, panodaki linkten video/ses/resim indirme — Gezgin sağ tık menüsünden."] = ("Image and media conversion, video/audio/image downloads from copied links — right from the Explorer menu.", "Afbeeldingen en media converteren, video/audio/afbeeldingen downloaden van gekopieerde links — vanuit het Verkenner-menu.", "Conversion d'images et de médias, téléchargement vidéo/audio/image depuis un lien copié — depuis le menu de l'Explorateur."),
        ["Sağ tık menüsü"] = ("Right-click menu", "Rechtsklikmenu", "Menu contextuel"),
        ["Sağ tık menüsüne ekle"] = ("Add to right-click menu", "Toevoegen aan rechtsklikmenu", "Ajouter au menu contextuel"),
        ["Sağ tık menüsünden kaldır"] = ("Remove from right-click menu", "Verwijderen uit rechtsklikmenu", "Retirer du menu contextuel"),
        ["Yeniden ekle"] = ("Add again", "Opnieuw toevoegen", "Ajouter à nouveau"),
        ["Kayıt HKCU\\Software\\Classes altına yazılır (yönetici izni gerekmez). Windows 11'de menü \"Daha fazla seçenek göster\" (Shift+F10) altında görünür. Görsel seçiliyse görsel araçları, video/ses seçiliyse medya araçları, boş alana tıklanırsa panodaki linkin indirme seçenekleri gelir."] = ("Registered under HKCU\\Software\\Classes (no admin rights needed). On Windows 11 the menu is under \"Show more options\" (Shift+F10). Images get image tools, video/audio get media tools, empty space offers downloads for the copied link.", "Geregistreerd onder HKCU\\Software\\Classes (geen beheerdersrechten nodig). In Windows 11 staat het menu onder \"Meer opties weergeven\" (Shift+F10). Afbeeldingen krijgen afbeeldingstools, video/audio mediatools, lege ruimte downloadopties voor de gekopieerde link.", "Enregistré sous HKCU\\Software\\Classes (sans droits administrateur). Sous Windows 11, le menu est dans « Afficher plus d'options » (Maj+F10). Images : outils d'image ; vidéo/audio : outils média ; espace vide : téléchargement du lien copié."),
        ["● Etkin — bu uygulamaya bağlı."] = ("● Active — linked to this app.", "● Actief — gekoppeld aan deze app.", "● Actif — lié à cette application."),
        ["● Kayıt eski bir konumu gösteriyor. Yeniden ekleyin."] = ("● The entry points to an old location. Add it again.", "● De registratie verwijst naar een oude locatie. Voeg opnieuw toe.", "● L'entrée pointe vers un ancien emplacement. Ajoutez-la à nouveau."),
        ["○ Ekli değil."] = ("○ Not added.", "○ Niet toegevoegd.", "○ Non ajouté."),
        ["Arka plan ve kısayollar"] = ("Background and shortcuts", "Achtergrond en sneltoetsen", "Arrière-plan et raccourcis"),
        ["Arka planda başlat"] = ("Start in background", "Op achtergrond starten", "Démarrer en arrière-plan"),
        ["Windows açılınca arka planda başlat"] = ("Start in the background with Windows", "Op de achtergrond starten met Windows", "Démarrer en arrière-plan avec Windows"),
        ["Gezgin'de tuş + sağ tık tekerleklerini kullan"] = ("Use key + right-click wheels in Explorer", "Toets + rechtsklik-wielen gebruiken in Verkenner", "Utiliser les roues touche + clic droit dans l'Explorateur"),
        ["Dönüştür tekerleği "] = ("Convert wheel ", "Converteerwiel ", "Roue Convertir "),
        ["Ctrl+Alt+L: panodaki linkin indirme tekerleği"] = ("Ctrl+Alt+L: download wheel for the copied link", "Ctrl+Alt+L: downloadwiel voor de gekopieerde link", "Ctrl+Alt+L : roue de téléchargement du lien copié"),
        ["3 kez hızlıca Ctrl / Alt / Shift: kısayol penceresi"] = ("Tap Ctrl / Alt / Shift 3× quickly: shortcuts window", "3× snel Ctrl / Alt / Shift: sneltoetsvenster", "3× rapidement Ctrl / Alt / Maj : fenêtre de raccourcis"),
        ["Seçimde ateş animasyonu 🔥"] = ("Fire animation when choosing 🔥", "Vuuranimatie bij kiezen 🔥", "Animation de feu au choix 🔥"),
        ["Tuş + sağ tık, uygulama arka planda çalışırken Gezgin ve masaüstünde Windows menüsünün yerine tekerleği açar. Ayarlar anında uygulanır."] = ("While the app runs in the background, key + right-click in Explorer and on the desktop opens the wheel instead of the Windows menu. Settings apply instantly.", "Terwijl de app op de achtergrond draait, opent toets + rechtsklik in Verkenner en op het bureaublad het wiel in plaats van het Windows-menu. Instellingen gelden direct.", "Quand l'application tourne en arrière-plan, touche + clic droit dans l'Explorateur et sur le bureau ouvre la roue au lieu du menu Windows. Les réglages s'appliquent immédiatement."),
        ["● Arka planda çalışıyor (sistem tepsisinde GKR simgesi)."] = ("● Running in the background (GKR icon in the system tray).", "● Draait op de achtergrond (GKR-pictogram in het systeemvak).", "● En arrière-plan (icône GKR dans la zone de notification)."),
