        ["bulunamadı"] = ("not found", "niet gevonden", "introuvable"),
        ["ffmpeg: medya dönüştürme · yt-dlp: link indirme · deno: YouTube için JavaScript çalışma zamanı. exe dosyalarını araç klasörüne kopyalamanız da yeterli."] = ("ffmpeg: media conversion · yt-dlp: link downloads · deno: JavaScript runtime for YouTube. Copying the .exe files into the tools folder also works.", "ffmpeg: mediaconversie · yt-dlp: links downloaden · deno: JavaScript-runtime voor YouTube. De .exe-bestanden in de toolsmap kopiëren werkt ook.", "ffmpeg : conversion média · yt-dlp : téléchargement de liens · deno : moteur JavaScript pour YouTube. Copier les .exe dans le dossier des outils fonctionne aussi."),
        ["Linkten indir"] = ("Download from link", "Downloaden van link", "Télécharger depuis un lien"),
