        ["Medya sayfası linki (yt-dlp destekli siteler)."] = ("Media page link (sites supported by yt-dlp).", "Link naar mediapagina (sites die yt-dlp ondersteunt).", "Lien de page média (sites pris en charge par yt-dlp)."),
        ["İndirme klasörü: {0}"] = ("Download folder: {0}", "Downloadmap: {0}", "Dossier de téléchargement : {0}"),
        ["Dosya dönüştür"] = ("Convert files", "Bestanden converteren", "Convertir des fichiers"),
        ["Dosyaları buraya sürükleyin ya da seçin."] = ("Drag files here or pick them.", "Sleep bestanden hierheen of kies ze.", "Glissez des fichiers ici ou choisissez-les."),
        ["◎  Dönüştürme tekerleğini aç"] = ("◎  Open conversion wheel", "◎  Converteerwiel openen", "◎  Ouvrir la roue de conversion"),
        ["Şu paketler winget ile resmi kaynaklarından kurulacak:\n\n  {0}\n\nDevam edilsin mi?"] = ("These packages will be installed with winget from their official sources:\n\n  {0}\n\nContinue?", "Deze pakketten worden met winget uit de officiële bronnen geïnstalleerd:\n\n  {0}\n\nDoorgaan?", "Ces paquets seront installés avec winget depuis leurs sources officielles :\n\n  {0}\n\nContinuer ?"),
        ["GKR Studio: Panodaki linki indir"] = ("GKR Studio: Download clipboard link", "GKR Studio: Link van klembord downloaden", "GKR Studio : Télécharger le lien copié"),
        ["Dil değişikliği pencereler yeniden açılınca tamamen uygulanır."] = ("The language change fully applies when windows are reopened.", "De taalwijziging geldt volledig zodra vensters opnieuw worden geopend.", "Le changement de langue s'applique entièrement à la réouverture des fenêtres."),

        ["GKR Studio'ya hoş geldiniz!\n\nŞunlar kurulsun mu?\n• Sağ tık menüsü\n• Windows açılınca arka planda başlatma\n• Şimdi arka planda başlatma (Shift/Ctrl/Alt + sağ tık tekerlekleri)\n\nHepsi Ayarlar'dan değiştirilebilir."] =
            ("Welcome to GKR Studio!\n\nSet up the following?\n• Right-click menu\n• Start in the background with Windows\n• Start in the background now (Shift/Ctrl/Alt + right-click wheels)\n\nEverything can be changed in Settings.",
             "Welkom bij GKR Studio!\n\nHet volgende instellen?\n• Rechtsklikmenu\n• Op de achtergrond starten met Windows\n• Nu op de achtergrond starten (Shift/Ctrl/Alt + rechtsklik-wielen)\n\nAlles is te wijzigen in Instellingen.",
             "Bienvenue dans GKR Studio !\n\nInstaller ceci ?\n• Menu contextuel\n• Démarrage en arrière-plan avec Windows\n• Démarrer en arrière-plan maintenant (roues Maj/Ctrl/Alt + clic droit)\n\nTout est modifiable dans les paramètres."),

        // ---------- macOS ----------
        ["Tamam"] = ("OK", "OK", "OK"),
        ["Evet"] = ("Yes", "Ja", "Oui"),
        ["Finder menüsü"] = ("Finder menu", "Finder-menu", "Menu du Finder"),
        ["Finder'a ekle"] = ("Add to Finder", "Toevoegen aan Finder", "Ajouter au Finder"),
        ["Finder'dan kaldır"] = ("Remove from Finder", "Verwijderen uit Finder", "Retirer du Finder"),
        ["Hızlı İşlemler"] = ("Quick Actions", "Snelle taken", "Actions rapides"),
        ["Finder'da dosyaya sağ tıklayın → Hızlı İşlemler → GKR Studio (Dönüştür / Araçlar / İşlemler). Görünmezse: Sistem Ayarları → Gizlilik ve Güvenlik → Uzantılar → Finder."] =
            ("Right-click a file in Finder → Quick Actions → GKR Studio (Convert / Tools / Actions). If missing: System Settings → Privacy & Security → Extensions → Finder.",
             "Klik met rechts op een bestand in Finder → Snelle taken → GKR Studio (Converteren / Gereedschap / Acties). Ontbreekt het: Systeeminstellingen → Privacy en beveiliging → Extensies → Finder.",
             "Clic droit sur un fichier dans le Finder → Actions rapides → GKR Studio (Convertir / Outils / Actions). Absent : Réglages Système → Confidentialité et sécurité → Extensions → Finder."),
        ["Oturum açılınca arka planda başlat"] = ("Start in the background at login", "Op de achtergrond starten bij inloggen", "Démarrer en arrière-plan à l'ouverture de session"),
        ["Finder'da tuş + sağ tık tekerleklerini kullan"] = ("Use key + right-click wheels in Finder", "Toets + rechtsklik-wielen gebruiken in Finder", "Utiliser les roues touche + clic droit dans le Finder"),
        ["⌃⌥L: panodaki linkin indirme tekerleği"] = ("⌃⌥L: download wheel for the copied link", "⌃⌥L: downloadwiel voor de gekopieerde link", "⌃⌥L : roue de téléchargement du lien copié"),
        ["Erişilebilirlik ayarlarını aç"] = ("Open Accessibility settings", "Toegankelijkheidsinstellingen openen", "Ouvrir les réglages d'accessibilité"),
        ["● Erişilebilirlik izni var."] = ("● Accessibility permission granted.", "● Toegankelijkheidstoestemming verleend.", "● Autorisation d'accessibilité accordée."),
        ["⚠ Tuş + sağ tık ve kısayollar için Erişilebilirlik izni gerekli: Sistem Ayarları → Gizlilik ve Güvenlik → Erişilebilirlik → GKR Studio'yı açın."] =
            ("⚠ Key + right-click and shortcuts need Accessibility permission: System Settings → Privacy & Security → Accessibility → enable GKR Studio.",
             "⚠ Toets + rechtsklik en sneltoetsen vereisen toegankelijkheidstoestemming: Systeeminstellingen → Privacy en beveiliging → Toegankelijkheid → schakel GKR Studio in.",
             "⚠ Touche + clic droit et raccourcis nécessitent l'accessibilité : Réglages Système → Confidentialité et sécurité → Accessibilité → activez GKR Studio."),
        ["Tuş + sağ tık ve kısayollar için Erişilebilirlik izni gerekiyor. Açılan pencerede GKR Studio'yı etkinleştirin."] =
            ("Key + right-click and shortcuts need Accessibility permission. Enable GKR Studio in the window that opens.",
             "Toets + rechtsklik en sneltoetsen vereisen toegankelijkheidstoestemming. Schakel GKR Studio in het geopende venster in.",
             "Touche + clic droit et raccourcis nécessitent l'accessibilité. Activez GKR Studio dans la fenêtre qui s'ouvre."),
        ["Tuş + sağ tık ve kısayollar için Erişilebilirlik izni gerekiyor. Açılan pencerede GKR Studio'yı etkinleştirin, sonra GKR Studio'yı yeniden başlatın."] =
            ("Key + right-click and shortcuts need Accessibility permission. Enable GKR Studio in the window that opens, then restart GKR Studio.",
             "Toets + rechtsklik en sneltoetsen vereisen toegankelijkheidstoestemming. Schakel GKR Studio in en start GKR Studio daarna opnieuw.",
             "Touche + clic droit et raccourcis nécessitent l'accessibilité. Activez GKR Studio puis redémarrez GKR Studio."),
        ["● Arka planda çalışıyor (menü çubuğunda GKR simgesi)."] = ("● Running in the background (GKR icon in the menu bar).", "● Draait op de achtergrond (GKR-pictogram in de menubalk).", "● En arrière-plan (icône GKR dans la barre des menus)."),
        ["Homebrew ile kur"] = ("Install with Homebrew", "Installeren met Homebrew", "Installer avec Homebrew"),
        ["ffmpeg: medya dönüştürme · yt-dlp: link indirme · deno: YouTube · tesseract: OCR · LibreOffice: Office belgeleri. Homebrew yoksa önce brew.sh adresinden kurun."] =
            ("ffmpeg: media conversion · yt-dlp: link downloads · deno: YouTube · tesseract: OCR · LibreOffice: Office documents. Install Homebrew from brew.sh first if needed.",
             "ffmpeg: mediaconversie · yt-dlp: links downloaden · deno: YouTube · tesseract: OCR · LibreOffice: Office-documenten. Installeer zo nodig eerst Homebrew via brew.sh.",
             "ffmpeg : conversion média · yt-dlp : téléchargements · deno : YouTube · tesseract : OCR · LibreOffice : documents Office. Installez d'abord Homebrew depuis brew.sh si besoin."),
        ["GKR Studio'ya hoş geldiniz!\n\nŞunlar kurulsun mu?\n• Finder Hızlı İşlemler menüsü\n• Oturum açılınca arka planda başlatma\n• Şimdi arka planda başlatma (menü çubuğu, Shift/Ctrl/Option + sağ tık)\n\nHepsi Ayarlar'dan değiştirilebilir."] =
            ("Welcome to GKR Studio!\n\nSet up the following?\n• Finder Quick Actions menu\n• Start in the background at login\n• Start in the background now (menu bar, Shift/Ctrl/Option + right-click)\n\nEverything can be changed in Settings.",
             "Welkom bij GKR Studio!\n\nHet volgende instellen?\n• Snelle taken in Finder\n• Op de achtergrond starten bij inloggen\n• Nu op de achtergrond starten (menubalk, Shift/Ctrl/Option + rechtsklik)\n\nAlles is te wijzigen in Instellingen.",
             "Bienvenue dans GKR Studio !\n\nInstaller ceci ?\n• Actions rapides du Finder\n• Démarrage en arrière-plan à l'ouverture de session\n• Démarrer en arrière-plan maintenant (barre des menus, Maj/Ctrl/Option + clic droit)\n\nTout est modifiable dans les paramètres."),

        ["Kısayollar için Erişilebilirlik iznini açın: Sistem Ayarları → Gizlilik ve Güvenlik → Erişilebilirlik → GKR Studio."] =
            ("Turn on Accessibility for the shortcuts: System Settings → Privacy & Security → Accessibility → GKR Studio.",
             "Schakel Toegankelijkheid in voor de sneltoetsen: Systeeminstellingen → Privacy en beveiliging → Toegankelijkheid → GKR Studio.",
             "Activez l'accessibilité pour les raccourcis : Réglages Système → Confidentialité et sécurité → Accessibilité → GKR Studio."),
        ["Finder'daki seçimi okumak için izin gerekiyor: Sistem Ayarları → Gizlilik ve Güvenlik → Otomasyon → GKR Studio → Finder."] =
            ("GKR Studio needs permission to read the Finder selection: System Settings → Privacy & Security → Automation → GKR Studio → Finder.",
             "GKR Studio heeft toestemming nodig om de Finder-selectie te lezen: Systeeminstellingen → Privacy en beveiliging → Automatisering → GKR Studio → Finder.",
             "GKR Studio a besoin d'une autorisation pour lire la sélection du Finder : Réglages Système → Confidentialité et sécurité → Automatisation → GKR Studio → Finder."),
        ["{0} + sağ tık bir tekerleğe atanmamış (Ayarlar → Kısayollar)."] =
            ("{0} + right-click is not assigned to a wheel (Settings → Shortcuts).",
             "{0} + rechtsklik is niet aan een wiel toegewezen (Instellingen → Sneltoetsen).",
